        if (!/^\+?[\d\s\-().]{7,20}$/.test(value)) {
          return 'Please enter a valid phone number (e.g. +1 (555) 000-0000).';
        }
        return null;
      },
    },
  };

  function validateField(key) {
    const { input, error, validate } = fields[key];
    const value = input.value.trim();
    const message = validate(value);

    error.textContent = message || '';
    input.classList.toggle('is-invalid', !!message);
    input.classList.toggle('is-valid', !message && value.length > 0);

    return !message;
  }

  // Live validation after first blur
  Object.keys(fields).forEach((key) => {
    const { input } = fields[key];

    input.addEventListener('blur', () => {
      input.dataset.touched = 'true';
      validateField(key);
    });

    input.addEventListener('input', () => {
      if (input.dataset.touched) validateField(key);
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    // Mark all fields as touched and validate
    const results = Object.keys(fields).map((key) => {
      fields[key].input.dataset.touched = 'true';
      return validateField(key);
    });

    if (results.every(Boolean)) {
      submitBtn.disabled = true;
      submitBtn.textContent = 'Sending…';

      // Simulate async submission
      setTimeout(() => {
        form.reset();
        Object.keys(fields).forEach((key) => {
          const { input } = fields[key];
          input.classList.remove('is-valid', 'is-invalid');
          delete input.dataset.touched;
        });
        submitBtn.hidden = true;
        successMsg.hidden = false;
      }, 800);
    }
  });
})();
